        .item { padding:2.5mm 0; border-top:.2mm dotted #9ca3af; }.item:first-of-type { border-top:0; padding-top:0; }.item-name { font-size:12px; font-weight:900; }.item-code { margin-top:.5mm; color:#4b5563; font-family:Consolas,monospace; font-size:10px; }.item-grid { display:grid; grid-template-columns:1fr auto; gap:.8mm 5mm; margin-top:1.5mm; font-size:10px; }.item-grid span:nth-child(even) { text-align:right; white-space:nowrap; font-weight:700; }.subtotal { display:flex; justify-content:space-between; gap:10px; margin-top:1.5mm; padding-top:1.5mm; border-top:.2mm dotted #9ca3af; font-size:11px; font-weight:900; }.deduction { display:flex; justify-content:space-between; gap:8px; padding:1.5mm 0; border-top:.2mm dotted #9ca3af; font-size:11px; }.deduction:first-of-type { border-top:0; padding-top:0; }.deduction small { display:block; margin-top:.6mm; color:#555; font-size:10px; }.empty { color:#555; font-size:11px; }
        .summary { padding:3mm 0; border-bottom:.3mm dashed #111; }.summary-row { display:flex; justify-content:space-between; gap:10px; margin:.8mm 0; font-size:11px; }.summary-row strong { text-align:right; }.grand-total { display:flex; justify-content:space-between; gap:10px; margin-top:2mm; padding-top:2mm; border-top:.3mm solid #111; font-size:13px; font-weight:900; }.grand-total strong { font-size:16px; white-space:nowrap; }.footer { padding-top:3mm; text-align:center; color:#444; font-size:10px; line-height:1.55; }.footer strong { color:#111; }
